"use client";
import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Send, Bot, User, Sparkles, Plus, 
  Stethoscope, BrainCircuit, Activity, 
  ChevronRight, Info, History, ShieldCheck,
  Mic, Paperclip, RefreshCcw, HeartPulse,
  Thermometer, AlertTriangle
} from 'lucide-react';

// --- TYPES ---
interface Message {
  id: string;
  role: 'assistant' | 'user';
  content: string;
  type?: 'prediction' | 'advice' | 'general';
}

export default function MedicalChatPage() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: '1', 
      role: 'assistant', 
      content: "Hello. I am your AI Medical Concierge. I can help guide your recovery or predict potential health risks based on your symptoms. How are you feeling today?",
      type: 'general'
    }
  ]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [predictionStats, setPredictionStats] = useState({ inflammationProbability: 75, recoveryDaysMin: 4, recoveryDaysMax: 6, riskLevel: "Low" });
  const chatContainerRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: input };
    setMessages(prev => [...prev, userMsg]);
    setInput("");
    setIsTyping(true);

    // Call REAL Backend API
    try {
      const response = await fetch('http://localhost:5000/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages: [...messages, userMsg] })
      });
      
      if (!response.ok) throw new Error("Failed to fetch");
      
      const aiResponse = await response.json();
      if (aiResponse.stats) {
        setPredictionStats(aiResponse.stats);
      }
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: aiResponse.role,
        content: aiResponse.content,
        type: aiResponse.type
      }]);
    } catch (err) {
      console.error(err);
      // Fallback
      setMessages(prev => [...prev, {
         id: (Date.now() + 1).toString(),
         role: 'assistant',
         content: "Sorry, I am having trouble connecting to my neural network.",
         type: 'general'
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] pt-28 pb-10 px-6">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8 h-[calc(100vh-160px)]">
        
        {/* --- LEFT: CHAT INTERFACE (8 Columns) --- */}
        <div className="lg:col-span-8 flex flex-col bg-white rounded-[3.5rem] border border-slate-100 shadow-xl shadow-indigo-100/20 overflow-hidden">
          
          {/* Chat Header */}
          <div className="p-6 border-b border-slate-50 flex items-center justify-between bg-white/50 backdrop-blur-md sticky top-0 z-10">
            <div className="flex items-center gap-4">
              <div className="h-12 w-12 rounded-2xl bg-gradient-to-tr from-indigo-600 to-purple-500 flex items-center justify-center text-white shadow-lg">
                <Bot size={24} />
              </div>
              <div>
                <h2 className="font-black text-[#1A1A3F] tracking-tight">CureLens AI Agent</h2>
                <div className="flex items-center gap-1.5">
                  <span className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Guidance Engine v2.0</span>
                </div>
              </div>
            </div>
            <button className="p-3 rounded-xl hover:bg-slate-50 text-slate-400 transition-colors">
              <History size={20} />
            </button>
          </div>

          {/* Chat Area */}
          <div 
            ref={chatContainerRef}
            className="flex-1 overflow-y-auto p-8 space-y-8 scroll-smooth"
          >
            <AnimatePresence initial={false}>
              {messages.map((msg) => (
                <motion.div
                  key={msg.id}
                  initial={{ opacity: 0, y: 10, scale: 0.95 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div className={`flex gap-4 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`h-10 w-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${
                      msg.role === 'assistant' ? 'bg-indigo-50 text-indigo-600' : 'bg-[#1A1A3F] text-white'
                    }`}>
                      {msg.role === 'assistant' ? <Sparkles size={18} /> : <User size={18} />}
                    </div>
                    
                    <div className={`p-6 rounded-[2rem] ${
                      msg.role === 'assistant' 
                        ? 'bg-slate-50 text-slate-700 rounded-tl-none border border-slate-100' 
                        : 'bg-[#6366F1] text-white rounded-tr-none shadow-lg shadow-indigo-100'
                    }`}>
                      {msg.type === 'prediction' && (
                        <div className="flex items-center gap-2 mb-3 text-[10px] font-black uppercase tracking-widest text-indigo-600 bg-indigo-100/50 w-fit px-3 py-1 rounded-full">
                          <BrainCircuit size={12} /> Predictive Insight
                        </div>
                      )}
                      <p className="text-sm leading-relaxed font-medium">{msg.content}</p>
                    </div>
                  </div>
                </motion.div>
              ))}

              {isTyping && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex justify-start">
                  <div className="bg-slate-50 p-6 rounded-[2rem] rounded-tl-none border border-slate-100 flex gap-2">
                    <span className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce" />
                    <span className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce delay-100" />
                    <span className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce delay-200" />
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          {/* Input Area */}
          <div className="p-8 bg-white border-t border-slate-50">
            <form 
              onSubmit={handleSendMessage}
              className="relative flex items-center bg-slate-50 border border-slate-100 rounded-3xl px-6 py-4 focus-within:border-indigo-300 transition-all shadow-inner"
            >
              <button type="button" className="text-slate-400 hover:text-indigo-600 transition-colors">
                <Paperclip size={20} />
              </button>
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Describe your symptoms or ask for guidance..."
                className="flex-1 bg-transparent border-none focus:ring-0 text-sm font-medium px-4 py-2"
              />
              <div className="flex items-center gap-3">
                <button type="button" className="text-slate-400 hover:text-indigo-600 transition-colors">
                  <Mic size={20} />
                </button>
                <button 
                  type="submit"
                  disabled={!input.trim()}
                  className="bg-[#6366F1] text-white p-3 rounded-2xl hover:bg-indigo-700 transition-all disabled:opacity-50 disabled:scale-95"
                >
                  <Send size={20} />
                </button>
              </div>
            </form>
          </div>
        </div>

        {/* --- RIGHT: PREDICTIONS & STATS (4 Columns) --- */}
        <div className="lg:col-span-4 space-y-6 overflow-y-auto pr-2">
          
          {/* Health Prediction Panel */}
          <div className="bg-[#1A1A3F] rounded-[3rem] p-8 text-white relative overflow-hidden">
            <div className="relative z-10">
              <div className="flex items-center gap-3 mb-8">
                <div className="h-10 w-10 rounded-xl bg-white/10 flex items-center justify-center">
                  <Activity size={20} className="text-indigo-400" />
                </div>
                <h3 className="font-bold text-lg">Real-time Prediction</h3>
              </div>

              <div className="space-y-6">
                <div>
                  <div className="flex justify-between text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">
                    <span>Inflammation Probability</span>
                    <span className="text-white">{predictionStats.inflammationProbability}%</span>
                  </div>
                  <div className="h-2 w-full bg-white/10 rounded-full overflow-hidden">
                    <motion.div initial={{ width: 0 }} animate={{ width: `${predictionStats.inflammationProbability}%` }} className="h-full bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.5)]" />
                  </div>
                </div>

                <div className="p-5 rounded-2xl bg-white/5 border border-white/10">
                   <p className="text-xs font-bold text-indigo-300 uppercase tracking-widest mb-2">Likely Recovery Time</p>
                   <p className="text-2xl font-black italic tracking-tighter">{predictionStats.recoveryDaysMin}-{predictionStats.recoveryDaysMax} Days</p>
                </div>

                <div className="flex items-center gap-3 p-4 bg-orange-500/10 border border-orange-500/20 rounded-2xl">
                  <AlertTriangle className="text-orange-500 shrink-0" size={18} />
                  <p className="text-[11px] font-medium text-orange-200">
                    {predictionStats.riskLevel === 'Low' ? 'Secondary infection risk is low but monitor temperature.' : 'Elevated risk detected. Contact your GP or monitor symptoms closely.'}
                  </p>
                </div>
              </div>
            </div>
            {/* Background Glow */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-600/20 blur-[60px]" />
          </div>

          {/* Vital Signs Mock */}
          <div className="bg-white rounded-[3rem] border border-slate-100 p-8 shadow-sm">
            <h4 className="text-[#1A1A3F] font-black uppercase tracking-widest text-[10px] mb-6">User Context Metrics</h4>
            <div className="space-y-4">
              {[
                { label: 'Avg Skin Temp', val: '36.8°C', icon: Thermometer, color: 'text-orange-500' },
                { label: 'Healing Progress', val: 'Level 2', icon: HeartPulse, color: 'text-rose-500' },
                { label: 'Data Points', val: '1,402', icon: ShieldCheck, color: 'text-emerald-500' },
              ].map((stat, i) => (
                <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100/50">
                  <div className="flex items-center gap-3">
                    <stat.icon size={16} className={stat.color} />
                    <span className="text-xs font-bold text-slate-500 uppercase">{stat.label}</span>
                  </div>
                  <span className="text-sm font-black text-[#1A1A3F]">{stat.val}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Quick Guides */}
          <div className="bg-indigo-50 border border-indigo-100 rounded-[2.5rem] p-6">
            <h4 className="font-bold text-indigo-900 text-sm mb-4">Suggested Guides</h4>
            <div className="space-y-2">
              <button className="w-full flex items-center justify-between p-3 bg-white rounded-xl text-xs font-bold text-indigo-600 hover:translate-x-1 transition-transform">
                Treating Swelling <ChevronRight size={14} />
              </button>
              <button className="w-full flex items-center justify-between p-3 bg-white rounded-xl text-xs font-bold text-indigo-600 hover:translate-x-1 transition-transform">
                When to see a Doctor <ChevronRight size={14} />
              </button>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Phone, AlertCircle, MapPin, Navigation, 
  ShieldAlert, UserPlus, Bell, Clock, 
  ChevronRight, Heart, Activity, Ambulance,
  Flame, Shield, Search, X, Info
} from 'lucide-react';

// --- MOCK EMERGENCY CONTACTS ---
const HELPLINE_NUMBERS = [
  { label: 'General Emergency', num: '112', icon: Shield, color: 'bg-rose-600' },
  { label: 'Ambulance', num: '102', icon: Ambulance, color: 'bg-emerald-600' },
  { label: 'Police Dept', num: '100', icon: ShieldAlert, color: 'bg-blue-600' },
  { label: 'Fire Services', num: '101', icon: Flame, color: 'bg-orange-600' },
];

export default function EmergencyHub() {
  const [sosActive, setSosActive] = useState(false);
  const [countdown, setCountdown] = useState(5);

  // SOS Activation Logic
  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (sosActive && countdown > 0) {
      timer = setTimeout(() => setCountdown(countdown - 1), 1000);
    } else if (sosActive && countdown === 0) {
      // Logic for actual emergency broadcast would go here
    }
    return () => clearTimeout(timer);
  }, [sosActive, countdown]);

  return (
    <div className="min-h-screen bg-[#FDFDFF] pt-28 pb-20 px-6">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-10">
        
        {/* --- LEFT: CRITICAL ACTIONS (SOS) --- */}
        <div className="lg:col-span-4 space-y-8">
          <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl shadow-rose-100 border border-rose-50 relative overflow-hidden">
            <div className="relative z-10 flex flex-col items-center text-center">
              <div className="h-16 w-16 bg-rose-50 rounded-2xl flex items-center justify-center text-rose-600 mb-6">
                <AlertCircle size={32} />
              </div>
              <h2 className="text-3xl font-black text-[#1A1A3F] tracking-tighter mb-4">SOS Trigger</h2>
              <p className="text-slate-400 text-sm font-medium mb-10 leading-relaxed">
                Hold the button below to alert emergency services and your designated contacts with your live location.
              </p>

              <button 
                onMouseDown={() => setSosActive(true)}
                onMouseUp={() => { if(countdown > 0) setSosActive(false); setCountdown(5); }}
                className={`relative h-48 w-48 rounded-full flex items-center justify-center transition-all duration-300 ${
                  sosActive ? 'scale-110 shadow-2xl shadow-rose-400 bg-rose-600' : 'bg-rose-500 shadow-xl shadow-rose-200 hover:bg-rose-600'
                }`}
              >
                <AnimatePresence mode="wait">
                  {sosActive ? (
                    <motion.div key="count" initial={{ scale: 0 }} animate={{ scale: 1 }} className="text-white text-5xl font-black">
                      {countdown}
                    </motion.div>
                  ) : (
                    <motion.div key="icon" className="text-white flex flex-col items-center">
                      <Bell size={48} className="animate-bounce" />
                      <span className="text-xs font-black uppercase tracking-[0.2em] mt-2">Hold to Send</span>
                    </motion.div>
                  )}
                </AnimatePresence>
                {/* Ripple Effect */}
                {sosActive && (
                  <motion.div 
                    initial={{ scale: 1, opacity: 0.5 }}
                    animate={{ scale: 2, opacity: 0 }}
                    transition={{ repeat: Infinity, duration: 1 }}
                    className="absolute inset-0 bg-rose-500 rounded-full"
                  />
                )}
              </button>
            </div>
          </div>

          {/* Quick Dial Cards */}
          <div className="grid grid-cols-2 gap-4">
            {HELPLINE_NUMBERS.map((help, i) => (
              <a key={i} href={`tel:${help.num}`} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex flex-col items-center text-center hover:shadow-lg transition-all group">
                <div className={`h-12 w-12 rounded-xl ${help.color} text-white flex items-center justify-center mb-4 group-hover:scale-110 transition-transform`}>
                  <help.icon size={20} />
                </div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{help.label}</span>
                <span className="text-lg font-black text-[#1A1A3F]">{help.num}</span>
              </a>
            ))}
          </div>
        </div>

        {/* --- RIGHT: NEAREST CARE FACILITIES --- */}
        <div className="lg:col-span-8 space-y-8">
          
          {/* Current Location Header */}
          <div className="bg-[#1A1A3F] rounded-[3rem] p-8 flex flex-col md:flex-row md:items-center justify-between gap-6 text-white overflow-hidden relative">
            <div className="flex items-center gap-6 z-10">
              <div className="h-14 w-14 rounded-2xl bg-indigo-500/20 backdrop-blur-md flex items-center justify-center text-indigo-400 border border-white/10">
                <MapPin size={24} />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-400 mb-1">Live Tracking Active</p>
                <h3 className="text-xl font-bold">Bahadurpally, Hyderabad</h3>
              </div>
            </div>
            <button className="bg-white/10 hover:bg-white/20 px-6 py-3 rounded-xl text-xs font-bold transition-all z-10 flex items-center gap-2 border border-white/10">
              <Navigation size={14} /> Update Coordinates
            </button>
            <div className="absolute right-0 top-0 h-full w-1/3 bg-gradient-to-l from-indigo-600/20 to-transparent pointer-events-none" />
          </div>

          {/* Nearest Hospitals List */}
          <div className="space-y-4">
            <div className="flex items-center justify-between px-4">
              <h4 className="font-black text-[#1A1A3F] uppercase tracking-widest text-xs">Nearest Medical Facilities</h4>
              <span className="text-indigo-600 font-bold text-xs cursor-pointer hover:underline">View on Map</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Facility 1 */}
              <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex flex-col justify-between hover:border-indigo-100 transition-all shadow-sm">
                <div className="flex justify-between items-start mb-6">
                  <div className="h-12 w-12 rounded-2xl bg-emerald-50 text-emerald-600 flex items-center justify-center font-black">SV</div>
                  <span className="bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">Open 24/7</span>
                </div>
                <div>
                  <h5 className="font-black text-lg text-[#1A1A3F] mb-1 leading-tight">SV Super Speciality Hospital</h5>
                  <p className="text-xs text-slate-400 font-medium mb-6 line-clamp-1">Bahadurpally, Hyderabad</p>
                  <div className="flex gap-2">
                    <button className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-xs">Navigate</button>
                    <button className="flex-1 border border-slate-100 py-3 rounded-xl font-bold text-xs text-slate-600">Call</button>
                  </div>
                </div>
              </div>

              {/* Facility 2 */}
              <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex flex-col justify-between hover:border-indigo-100 transition-all shadow-sm">
                <div className="flex justify-between items-start mb-6">
                  <div className="h-12 w-12 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black">MN</div>
                  <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">Trauma Center</span>
                </div>
                <div>
                  <h5 className="font-black text-lg text-[#1A1A3F] mb-1 leading-tight">Malla Reddy Narayana Hospital</h5>
                  <p className="text-xs text-slate-400 font-medium mb-6 line-clamp-1">Suraram 'X' Roads, Jeedimetla</p>
                  <div className="flex gap-2">
                    <button className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-xs">Navigate</button>
                    <button className="flex-1 border border-slate-100 py-3 rounded-xl font-bold text-xs text-slate-600">Call</button>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Emergency Protocols */}
          <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-sm">
             <div className="p-8 border-b border-slate-50 flex items-center justify-between">
                <h4 className="font-black text-[#1A1A3F] uppercase tracking-widest text-xs">Standard Protocols</h4>
                <div className="flex gap-2">
                  <button className="px-4 py-2 rounded-xl bg-slate-50 text-[10px] font-black text-slate-500 uppercase tracking-widest border border-slate-100">Injuries</button>
                  <button className="px-4 py-2 rounded-xl bg-indigo-600 text-[10px] font-black text-white uppercase tracking-widest shadow-md shadow-indigo-100">Cuts/Burns</button>
                </div>
             </div>
             <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-6">
                {[
                  { title: 'Control Bleeding', desc: 'Apply direct pressure with a clean cloth.', icon: Heart },
                  { title: 'Keep Calm', desc: 'Slow, deep breaths to avoid hyperventilation.', icon: Activity },
                  { title: 'Wait for Help', desc: 'Stay in a safe, visible location.', icon: Clock },
                ].map((step, i) => (
                  <div key={i} className="space-y-3">
                    <div className="h-10 w-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center">
                      <step.icon size={18} />
                    </div>
                    <h5 className="font-bold text-[#1A1A3F] text-sm leading-tight">{step.title}</h5>
                    <p className="text-xs text-slate-400 leading-relaxed font-medium">{step.desc}</p>
                  </div>
                ))}
             </div>
          </div>

        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { motion } from 'framer-motion';
import { LayoutDashboard, Scan, MessageSquare, AlertCircle, User, ChevronLeft } from 'lucide-react';
import { cn } from "@/lib/utils";

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const [isSidebarOpen, setSidebarOpen] = useState(true);

  // Updated to match your separate folder names
  const menuItems = [
    { id: 'scan', label: 'AI Scanner', icon: Scan, href: '/scan' },
    { id: 'chat', label: 'Medical AI Chat', icon: MessageSquare, href: '/chat' },
    { id: 'emergency', label: 'SOS Hub', icon: AlertCircle, href: '/emergency', color: 'text-rose-500' },
  ];

  return (
    <div className="flex min-h-screen bg-[#FDFDFF] text-[#1A1A3F]">
      <motion.aside 
        animate={{ width: isSidebarOpen ? 280 : 80 }}
        className="fixed left-0 top-0 h-full bg-white border-r border-slate-100 z-50 flex flex-col transition-all shadow-sm"
      >
        <div className="p-6 flex items-center gap-3">
          <div className="h-10 w-10 shrink-0 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-black shadow-lg">C</div>
          {isSidebarOpen && <span className="font-black text-xl tracking-tighter">CureLens<span className="text-indigo-600">.Ai</span></span>}
        </div>

        <nav className="flex-1 px-4 py-10 space-y-2">
          {menuItems.map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link key={item.id} href={item.href}>
                <div className={cn(
                  "w-full flex items-center gap-4 px-4 py-4 rounded-2xl transition-all cursor-pointer group mb-1",
                  isActive ? "bg-indigo-50 text-indigo-600 shadow-sm" : "text-slate-400 hover:bg-slate-50 hover:text-slate-600"
                )}>
                  <item.icon className={cn("shrink-0", isActive ? (item.color || 'text-indigo-600') : '')} size={22} />
                  {isSidebarOpen && <span className="text-sm font-bold tracking-tight">{item.label}</span>}
                </div>
              </Link>
            );
          })}
        </nav>
      </motion.aside>

      <main className={cn("flex-1 transition-all duration-300", isSidebarOpen ? "ml-[280px]" : "ml-[80px]")}>
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-50 flex items-center justify-between px-10 sticky top-0 z-40">
          <div className="flex items-center gap-4">
             <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">
                <ChevronLeft className={cn("transition-transform", !isSidebarOpen && "rotate-180")} size={20} />
             </button>
             <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400">Diagnostic Portal</h2>
          </div>
        </header>
        <div className="p-10">{children}</div>
      </main>
    </div>
  );
}

