"use client";
import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { 
  User, Mail, Shield, Bell, MapPin, 
  Camera, Fingerprint, CreditCard, 
  ChevronRight, Save, Key, Smartphone
} from 'lucide-react';
import { useUser } from '@clerk/nextjs';

export default function ProfilePage() {
  const { user } = useUser();
  const [activeTab, setActiveTab] = useState('Personal');

  const tabs = ['Personal', 'Security', 'Billing', 'Preferences'];

  return (
    <div className="min-h-screen bg-[#FDFDFF] p-6 lg:p-12 pb-24">
      <div className="max-w-5xl mx-auto">
        
        {/* --- PROFILE HEADER --- */}
        <section className="relative mb-12">
          <div className="h-48 w-full bg-gradient-to-r from-indigo-600 to-indigo-900 rounded-[3rem] shadow-2xl overflow-hidden relative">
            <div className="absolute inset-0 opacity-10 flex items-center justify-center">
              <Fingerprint size={300} />
            </div>
          </div>
          
          <div className="absolute -bottom-10 left-12 flex items-end gap-6">
            <div className="relative group">
              <img 
                src={user?.imageUrl} 
                alt="Profile" 
                className="h-32 w-32 rounded-[2.5rem] border-4 border-white shadow-xl object-cover"
              />
              <button className="absolute bottom-2 right-2 p-2 bg-white rounded-xl shadow-lg text-indigo-600 hover:scale-110 transition-all">
                <Camera size={18} />
              </button>
            </div>
            <div className="mb-4">
              <h1 className="text-4xl font-black tracking-tighter text-[#1A1A3F]">{user?.fullName}</h1>
              <p className="text-white/70 bg-indigo-900/50 backdrop-blur-md px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest inline-block mt-2">
                Patient ID: {user?.id.slice(-8).toUpperCase()}
              </p>
            </div>
          </div>
        </section>

        {/* --- NAVIGATION TABS --- */}
        <div className="flex items-center gap-2 bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm w-fit mb-10 ml-4">
          {tabs.map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-8 py-3 rounded-[1.5rem] text-xs font-black uppercase tracking-widest transition-all ${
                activeTab === tab ? 'bg-[#1A1A3F] text-white shadow-lg' : 'text-slate-400 hover:text-indigo-600'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* --- MAIN CONTENT AREA --- */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          
          {/* Left Column: Form Fields */}
          <div className="lg:col-span-8 space-y-6">
            <motion.div 
              key={activeTab}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-white rounded-[3.5rem] border border-slate-100 p-10 shadow-sm"
            >
              <h3 className="text-2xl font-black text-[#1A1A3F] mb-8 flex items-center gap-3">
                {activeTab} <span className="text-indigo-600">Information.</span>
              </h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <ProfileInput label="First Name" value={user?.firstName || ""} icon={User} />
                <ProfileInput label="Last Name" value={user?.lastName || ""} icon={User} />
                <ProfileInput label="Email Address" value={user?.primaryEmailAddress?.emailAddress || ""} icon={Mail} disabled />
                <ProfileInput label="Phone Number" value="+91 ••••• ••432" icon={Smartphone} />
                <ProfileInput label="Location" value="Hyderabad, TS" icon={MapPin} />
                <ProfileInput label="Language" value="English (Global)" icon={Shield} />
              </div>

              <div className="mt-12 pt-8 border-t border-slate-50 flex justify-between items-center">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  Last verified: 2 hours ago
                </p>
                <button className="flex items-center gap-3 bg-indigo-600 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-indigo-100">
                  <Save size={16} /> Save Changes
                </button>
              </div>
            </motion.div>
          </div>

          {/* Right Column: Cards */}
          <div className="lg:col-span-4 space-y-6">
            <div className="bg-[#1A1A3F] rounded-[3rem] p-8 text-white relative overflow-hidden group">
              <Key className="absolute top-[-20px] right-[-20px] text-white/5 group-hover:rotate-12 transition-transform duration-700" size={180} />
              <h4 className="text-lg font-black mb-2 relative z-10">Security Status</h4>
              <p className="text-xs text-indigo-300 font-medium mb-6 relative z-10">Two-factor authentication is active via clinical SMS.</p>
              <button className="w-full py-4 bg-white/10 hover:bg-white/20 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all relative z-10">
                Manage Security
              </button>
            </div>

            <div className="bg-white rounded-[3rem] border border-slate-100 p-8 shadow-sm">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                <CreditCard size={14} /> Payment Method
              </h4>
              <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div className="h-10 w-20 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center text-white italic font-black text-xs">
                  VISA
                </div>
                <div>
                  <p className="text-xs font-black text-[#1A1A3F]">•••• 9921</p>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter italic">Exp 12/28</p>
                </div>
                <ChevronRight size={16} className="ml-auto text-slate-300" />
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

// --- HELPER COMPONENT: INPUT ---
function ProfileInput({ label, value, icon: Icon, disabled = false }: any) {
  return (
    <div className="space-y-2">
      <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">
        {label}
      </label>
      <div className={`flex items-center gap-3 px-5 py-4 rounded-2xl border transition-all ${
        disabled ? 'bg-slate-50 border-slate-100 opacity-60' : 'bg-white border-slate-100 focus-within:border-indigo-600'
      }`}>
        <Icon size={16} className="text-slate-300" />
        <input 
          defaultValue={value} 
          disabled={disabled}
          className="bg-transparent border-none outline-none text-sm font-bold text-[#1A1A3F] w-full"
        />
      </div>
    </div>
  );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { 
  HeartPulse, LayoutDashboard, Beaker, MessageSquare, 
  AlertCircle, LogOut, Settings, User as UserIcon, 
  ShieldCheck, Activity, Pill, History, ChevronDown
} from 'lucide-react';
import { SignedIn, SignedOut, SignInButton, useClerk, useUser } from '@clerk/nextjs';
import { motion, AnimatePresence } from 'framer-motion';

export function Navbar() {
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const { user } = useUser();
  const { signOut } = useClerk();
  const menuRef = useRef<HTMLDivElement>(null);

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setIsMegaMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <header className="fixed top-0 left-0 right-0 z-[100] px-6 py-4 bg-white border-b border-slate-100">
      <nav className="mx-auto max-w-7xl flex items-center justify-between h-16">
        
        {/* --- LOGO --- */}
        <Link href="/" className="flex items-center gap-3">
          <div className="h-10 w-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-100">
            <HeartPulse className="text-white w-6 h-6" />
          </div>
          <span className="font-black text-[#1A1A3F] text-xl tracking-tighter uppercase leading-none">CureLens <br/><span className="text-[8px] text-indigo-500 tracking-[0.3em]">AI.HEALTH</span></span>
        </Link>

        {/* --- AUTHENTICATION ACTIONS --- */}
        <div className="flex items-center gap-4">
          <SignedOut>
            <SignInButton mode="modal">
              <button className="bg-[#1A1A3F] text-white px-7 py-3 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all">
                Login / Sign Up
              </button>
            </SignInButton>
          </SignedOut>

          <SignedIn>
            <div className="relative" ref={menuRef}>
              {/* TRIGGER: CUSTOM AVATAR BOX */}
              <button 
                onClick={() => setIsMegaMenuOpen(!isMegaMenuOpen)}
                className="flex items-center gap-3 p-1.5 pr-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-indigo-200 transition-all active:scale-95"
              >
                <img 
                  src={user?.imageUrl} 
                  alt="avatar" 
                  className="h-10 w-10 rounded-xl object-cover border-2 border-white shadow-sm" 
                />
                <div className="flex flex-col items-start leading-tight">
                  <span className="text-[11px] font-black text-[#1A1A3F] uppercase tracking-tighter">My Portal</span>
                  <span className="text-[9px] font-bold text-emerald-500 uppercase tracking-widest">Authorized</span>
                </div>
                <ChevronDown size={14} className={`text-slate-400 transition-transform duration-300 ${isMegaMenuOpen ? 'rotate-180' : ''}`} />
              </button>

              {/* --- THE MEGA MENU --- */}
              <AnimatePresence>
                {isMegaMenuOpen && (
                  <motion.div 
                    initial={{ opacity: 0, y: 15, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 15, scale: 0.95 }}
                    className="absolute top-[120%] right-0 w-[420px] bg-white rounded-[2.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.15)] border border-slate-100 p-8 overflow-hidden"
                  >
                    {/* Header Info */}
                    <div className="flex items-center gap-4 pb-8 mb-6 border-b border-slate-50">
                      <img src={user?.imageUrl} alt="avatar" className="h-14 w-14 rounded-2xl object-cover" />
                      <div>
                        <h4 className="font-black text-lg text-[#1A1A3F]">{user?.fullName}</h4>
                        <p className="text-xs font-medium text-slate-400">{user?.primaryEmailAddress?.emailAddress}</p>
                      </div>
                    </div>

                    {/* Mega Menu Grid */}
                    <div className="grid grid-cols-2 gap-x-8 gap-y-2">
                      <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 mb-3">Core Modules</p>
                        <MegaLink icon={LayoutDashboard} label="Dashboard" href="/dashboard" />
                        <MegaLink icon={Beaker} label="Lab Diagnostics" href="/labs" />
                        <MegaLink icon={MessageSquare} label="AI Consultant" href="/chat" />
                        <MegaLink icon={AlertCircle} label="SOS Center" href="/emergency" color="text-rose-500" />
                      </div>

                      <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 mb-3">Patient Records</p>
                        <MegaLink icon={History} label="Scan History" href="/history" />
                        <MegaLink icon={Pill} label="Profile" href="/profile" />
                        <MegaLink icon={Activity} label="About Us" href="/about" />
                        <MegaLink icon={Settings} label="Preferences" href="/user-profile" />
                      </div>
                    </div>

                    {/* Logout Footer */}
                    <div className="mt-8 pt-6 border-t border-slate-50">
                      <button 
                        onClick={() => signOut()}
                        className="w-full flex items-center justify-between p-4 bg-slate-50 rounded-2xl hover:bg-rose-50 hover:text-rose-600 transition-all group"
                      >
                        <div className="flex items-center gap-3">
                          <LogOut size={18} />
                          <span className="text-sm font-black uppercase tracking-widest">Terminate Session</span>
                        </div>
                        <ShieldCheck size={16} className="opacity-20 group-hover:opacity-100" />
                      </button>
                    </div>
                    
                    {/* Decorative Background Icon */}
                    <HeartPulse size={120} className="absolute bottom-[-30px] right-[-30px] text-slate-50 -z-10" />
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </SignedIn>
        </div>
      </nav>
    </header>
  );
}

// Sub-component for Menu Links
function MegaLink({ icon: Icon, label, href, color = "text-slate-500" }: any) {
  return (
    <Link href={href} className="flex items-center gap-3 p-3 rounded-xl hover:bg-slate-50 transition-all group">
      <div className={`h-8 w-8 rounded-lg bg-white shadow-sm border border-slate-100 flex items-center justify-center ${color} group-hover:bg-indigo-600 group-hover:text-white transition-all`}>
        <Icon size={16} />
      </div>
      <span className="text-[13px] font-bold text-[#1A1A3F] group-hover:text-indigo-600 transition-colors">{label}</span>
    </Link>
  );
}
